{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In mice, intravenous injection produced extremely low brain radioactivity (<1% ID/mL over 60 min), indicating no meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "An in vivo pharmacokinetic study found no compound in brain tissue (LLOQ = 10 ng/mL), indicating failure to cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Human PET showed rapid brain distribution with 3–4% of injected radioactivity at peak, demonstrating meaningful CNS access in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence shows negligible or poor brain uptake after systemic administration across rodent PET/PK and in situ perfusion studies. The single positive human/NHP PET record is outweighed by the higher-scoring negative records and is itself accompanied by rodent efflux-limited low uptake.",
  "evidence_gaps": [
    "The only positive evidence comes from one molecule with species-dependent brain uptake (low rodent baseline due to ABC efflux vs high human/NHP uptake), making its transferability uncertain.",
    "Most negative records are from rodents or in situ perfusion; direct human CNS exposure data are not available for those molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

